/* ============================================================================
   PLAN_DESARROLLO_5  (28/10/2026)  marca PL_DES_V5  -- requiere PLAN_DESARROLLO_4 y PLAN_CSS_V46 aplicados
   ----------------------------------------------------------------------------
   - Detalle del item: sin la lista de subitems (se eligen en el arbol).
   - Estado de la accion: Pendiente / En proceso automatico por el desarrollo realizado
     (primer desarrollo realizado -> En proceso; sin desarrollos realizados -> Pendiente).
     En espera / Cumplida / Cancelada se eligen con Editar (reglas PL_DES_V3).
   - Responsable de la accion del plan: el rol viaja en la opcion (el js no ofrece al analista).
   - Trabajo de la visita (boceto B): indicadores, por consultor, trabajado y proxima visita.
   - Assets: vct-proyecto-v360.css ?v=47 y vct-proyecto-v360.js ?v=39 (subir los dos archivos).
   Si alguno de los puntos no se encuentra en la definicion vigente, NO se cambia nada.
   Re-ejecutable: si la marca PL_DES_V5 ya esta, avisa y no hace nada.  SSMS: F5.
   ============================================================================ */
USE [MuhlePROD];
SET NOCOUNT ON;
GO
DECLARE @D NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID('dbo.VCT_MAIN_PROYECTO_V360')),
        @NE NVARCHAR(MAX), @RE NVARCHAR(MAX), @N INT, @F NVARCHAR(MAX) = N'', @s INT, @p INT;
IF @D IS NULL
    PRINT 'FALLO: no se encontro dbo.VCT_MAIN_PROYECTO_V360.';
ELSE IF CHARINDEX(N'PL_DES_V5', @D) > 0
    PRINT 'OK   el parche PL_DES_V5 ya estaba aplicado: no se hizo nada.';
ELSE IF CHARINDEX(N'PL_DES_V4', @D) = 0
    PRINT 'FALLO: falta aplicar antes PLAN_DESARROLLO_4.sql. No se cambio nada.';
ELSE
BEGIN
    SET @D = REPLACE(@D, NCHAR(13) + NCHAR(10), NCHAR(10));
    /* assets */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'vct-proyecto-v360.css?v=46"><script src="../js/vct-proyecto-v360.js?v=38"';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'vct-proyecto-v360.css?v=47"><script src="../js/vct-proyecto-v360.js?v=39"';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' assets(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* det_padre */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'''<div class="vct-plt-det" data-pl-det="'' + CONVERT(VARCHAR(20), T.ID) + ''" hidden>''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'''<div class="vct-plt-det" data-pl-det="'' + CONVERT(VARCHAR(20), T.ID) + ''" data-pl-padre="'' + CASE WHEN T.NIV = 3 THEN ISNULL(CONVERT(VARCHAR(20), T.PADRE), '''') ELSE '''' END + ''" hidden>''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' det_padre(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* det_subs */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'+ CASE WHEN T.NIV = 2 AND T.HIJOS > 0 THEN ''<div class="vct-plt-sec">Sub&iacute;tems (''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'+ CASE WHEN 1 = 0 AND T.NIV = 2 AND T.HIJOS > 0 THEN ''<div class="vct-plt-sec">Sub&iacute;tems (''   /* PL_DES_V5: los subitems se eligen en el arbol */';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' det_subs(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* acc_auto */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'h de desarrollo realizado: no se puede cancelar. Elimin'' + CHAR(225) + '' primero su desarrollo.'';' + NCHAR(10) + N'            END;';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'h de desarrollo realizado: no se puede cancelar. Elimin'' + CHAR(225) + '' primero su desarrollo.'';' + NCHAR(10) + N'                /* PL_DES_V5: Pendiente / En proceso no se eligen: los define el desarrollo realizado */' + NCHAR(10) + N'                IF @ERR = '''' AND @PA_ACC IS NOT NULL AND @PA_EST IN (ISNULL(@PL_PEND, -1), ISNULL(@PL_PROC, -1)) AND @PL_PEND IS NOT NULL AND @PL_PROC IS NOT NULL' + NCHAR(10) + N'                    SET @PA_EST = CASE WHEN EXISTS (SELECT 1 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_ACCION = @PA_ACC AND D.TIPO = ''REALIZADO'') THEN @PL_PROC ELSE @PL_PEND END;' + NCHAR(10) + N'            END;';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' acc_auto(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* des_auto */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'                    SET @MSG = ''Desarrollo eliminado.'';' + NCHAR(10) + N'                END;' + NCHAR(10) + N'';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'                    SET @MSG = ''Desarrollo eliminado.'';' + NCHAR(10) + N'                END;' + NCHAR(10) + N'                /* PL_DES_V5: estado automatico de la accion por su desarrollo realizado (Pendiente <-> En proceso) */' + NCHAR(10) + N'                IF @B_CMD IN (''PV_PL_DES_GUARDAR'',''PV_PL_DES_BORRAR'') AND @PL_PROC IS NOT NULL AND @PL_PEND IS NOT NULL' + NCHAR(10) + N'                BEGIN' + NCHAR(10) + N'                    DECLARE @AU_ACC INT, @AU_EST INT, @AU_R BIT = 0;' + NCHAR(10) + N'                    SET @AU_ACC = CASE WHEN @B_CMD = ''PV_PL_DES_BORRAR'' THEN @DS_OLD_ACC ELSE @DS_ACC END;' + NCHAR(10) + N'                    SELECT @AU_EST = ID_ESTADO FROM dbo.VCT_ACCIONES WHERE ID = @AU_ACC;' + NCHAR(10) + N'                    IF EXISTS (SELECT 1 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_ACCION = @AU_ACC AND D.TIPO = ''REALIZADO'') SET @AU_R = 1;' + NCHAR(10) + N'                    IF @AU_R = 1 AND @AU_EST = @PL_PEND' + NCHAR(10) + N'                    BEGIN' + NCHAR(10) + N'                        UPDATE dbo.VCT_ACCIONES SET ID_ESTADO = @PL_PROC, FECHA_UPD = GETDATE(), USUARIO_UPD = @IAGENTE WHERE ID = @AU_ACC;' + NCHAR(10) + N'                        INSERT INTO dbo.VCT_ACCIONES_HISTORIAL (ID_ACCION, ID_ESTADO_ANTERIOR, ID_ESTADO_NUEVO, ACCION, DESCRIPCION, TIPO_ACTOR, FECHA, USUARIO)' + NCHAR(10) + N'                        VALUES (@AU_ACC, @AU_EST, @PL_PROC, ''ESTADO_AUTOMATICO'', ''Pasa a En proceso: se carg'' + CHAR(243) + '' su primer desarrollo realizado.'', ''SISTEMA'', GETDATE(), @IAGENTE);' + NCHAR(10) + N'                        SET @MSG = @MSG + '' La acci'' + CHAR(243) + ''n pas'' + CHAR(243) + '' a En proceso.'';' + NCHAR(10) + N'                    END' + NCHAR(10) + N'                    ELSE IF @AU_R = 0 AND @AU_EST = @PL_PROC' + NCHAR(10) + N'                    BEGIN' + NCHAR(10) + N'                        UPDATE dbo.VCT_ACCIONES SET ID_ESTADO = @PL_PEND, FECHA_UPD = GETDATE(), USUARIO_UPD = @IAGENTE WHERE ID = @AU_ACC;' + NCHAR(10) + N'                        INSERT INTO dbo.VCT_ACCIONES_HISTORIAL (ID_ACCION, ID_ESTADO_ANTERIOR, ID_ESTADO_NUEVO, ACCION, DESCRIPCION, TIPO_ACTOR, FECHA, USUARIO)' + NCHAR(10) + N'                        VALUES (@AU_ACC, @AU_EST, @PL_PEND, ''ESTADO_AUTOMATICO'', ''Vuelve a Pendiente: no le quedan desarrollos realizados.'', ''SISTEMA'', GETDATE(), @IAGENTE);' + NCHAR(10) + N'                        SET @MSG = @MSG + '' La acci'' + CHAR(243) + ''n volvi'' + CHAR(243) + '' a Pendiente.'';' + NCHAR(10) + N'                    END;' + NCHAR(10) + N'                END;' + NCHAR(10) + N'';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' des_auto(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* ropt_rol */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'SELECT ''<option value="EQ:'' + CONVERT(VARCHAR(20), ID) + ''">''';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'SELECT ''<option value="EQ:'' + CONVERT(VARCHAR(20), ID) + ''" data-rol="'' + ISNULL(ROL_COD, '''') + ''">''';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' ropt_rol(' + CONVERT(NVARCHAR(10), @N) + N')';
    /* agw */
    SET @NE = CONVERT(NVARCHAR(MAX), N'')+ N'        SELECT @AGW = ISNULL((' + NCHAR(10) + N'            SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw" data-pv-agw="'' + CONVERT(VARCHAR(20), A.ID) + ''" hidden''' + NCHAR(10) + N'                 + '' data-x="'' + REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(A.INST + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''\'',''/''),''"'',''''''''),CHAR(10),'' ''),CHAR(13),'' ''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''"''' + NCHAR(10) + N'                 + '' data-d1="'' + CONVERT(VARCHAR(10), A.DESDE, 120) + ''" data-d2="'' + CONVERT(VARCHAR(10), A.HASTA, 120) + ''"''' + NCHAR(10) + N'                 + '' data-tit="Visita del '' + CONVERT(VARCHAR(10), A.DESDE, 103) + CASE WHEN A.HASTA > A.DESDE THEN '' al '' + CONVERT(VARCHAR(10), A.HASTA, 103) ELSE '''' END + ''"''' + NCHAR(10) + N'                 + '' data-sub="'' + REPLACE(REPLACE(REPLACE(REPLACE(A.INST + '' - '' + CASE A.SIT WHEN ''e'' THEN ''Ejecutada'' WHEN ''c'' THEN ''Confirmada'' ELSE ''Pendiente'' END + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-k"><div><small>Horas de la visita</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), A.HT)), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Volcadas en desarrollos</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Sin detallar (informe)</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN A.HT > ISNULL(R.H, 0) THEN A.HT - ISNULL(R.H, 0) ELSE 0 END)), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Planificados</small><b>'' + CONVERT(VARCHAR(10), ISNULL(R.NP, 0)) + ''</b></div></div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-cols">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">Trabajado en la visita<span class="vct-360-badge is-active">'' + CONVERT(VARCHAR(10), ISNULL(R.NR, 0)) + '' &middot; '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</span></div>''' + NCHAR(10) + N'                 + ISNULL(NULLIF((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN ''<span class="vct-pl-code">'' + REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span> '' ELSE '''' END' + NCHAR(10) + N'                                      + ''<small>'' + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</small><b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN ''<em>Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</em>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span></div><span class="vct-pv-agw-hs">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + '' h</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''<div class="vct-plt-empty">Sin desarrollos realizados en esta visita.</div>'')' + NCHAR(10) + N'                 + ''</div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">Planificado para la visita<span class="vct-360-badge is-planned">'' + CONVERT(VARCHAR(10), ISNULL(R.NP, 0)) + ''</span></div>''' + NCHAR(10) + N'                 + ISNULL(NULLIF((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN ''<span class="vct-pl-code">'' + REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span> '' ELSE '''' END' + NCHAR(10) + N'                                      + ''<small>'' + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</small><b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span></div><span class="vct-pv-agw-hs">&ndash;</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''PLANIFICADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''<div class="vct-plt-empty">Nada planificado para esta visita.</div>'')' + NCHAR(10) + N'                 + ''</div></div></div>''' + NCHAR(10) + N'            FROM #AGV A' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END) AS H,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS NR,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END) AS NP' + NCHAR(10) + N'                         FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID) R' + NCHAR(10) + N'            ORDER BY A.DESDE, A.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');';
    SET @RE = CONVERT(NVARCHAR(MAX), N'')+ N'        /* PL_DES_V5: trabajo de la visita (boceto B): indicadores, por consultor, trabajado y lo que queda para la proxima visita */' + NCHAR(10) + N'        SELECT @AGW = ISNULL((' + NCHAR(10) + N'            SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw" data-pv-agw="'' + CONVERT(VARCHAR(20), A.ID) + ''" hidden''' + NCHAR(10) + N'                 + '' data-x="'' + REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(A.INST + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''\'',''/''),''"'',''''''''),CHAR(10),'' ''),CHAR(13),'' ''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''"''' + NCHAR(10) + N'                 + '' data-d1="'' + CONVERT(VARCHAR(10), A.DESDE, 120) + ''" data-d2="'' + CONVERT(VARCHAR(10), A.HASTA, 120) + ''"''' + NCHAR(10) + N'                 + '' data-tit="Visita del '' + CONVERT(VARCHAR(10), A.DESDE, 103) + CASE WHEN A.HASTA > A.DESDE THEN '' al '' + CONVERT(VARCHAR(10), A.HASTA, 103) ELSE '''' END + ''"''' + NCHAR(10) + N'                 + '' data-sub="'' + REPLACE(REPLACE(REPLACE(REPLACE(A.INST + '' - '' + CASE A.SIT WHEN ''e'' THEN ''Ejecutada'' WHEN ''c'' THEN ''Confirmada'' ELSE ''Pendiente'' END + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-k"><div><small>Horas de la visita</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), A.HT)), ''.0'', '''') + '' h</b><em>'' + CONVERT(VARCHAR(10), ISNULL(NC.N, 0)) + '' consultor'' + CASE WHEN ISNULL(NC.N, 0) = 1 THEN '''' ELSE ''es'' END + ''</em></div>''' + NCHAR(10) + N'                 + ''<div><small>Volcadas en desarrollos</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</b><em>'' + CONVERT(VARCHAR(10), CASE WHEN A.HT > 0 THEN CONVERT(INT, ROUND(ISNULL(R.H, 0) * 100.0 / A.HT, 0)) ELSE 0 END) + '' %</em></div>''' + NCHAR(10) + N'                 + ''<div><small>Sin detallar (informe)</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN A.HT > ISNULL(R.H, 0) THEN A.HT - ISNULL(R.H, 0) ELSE 0 END)), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Transcurrido desde 1&ordf; visita</small><b>'' + CASE WHEN @F_V1 IS NULL THEN ''-'' ELSE CONVERT(VARCHAR(10), DATEDIFF(DAY, @F_V1, A.DESDE)) + '' d&iacute;as'' END + ''</b>''' + NCHAR(10) + N'                 + CASE WHEN @F_V1 IS NULL THEN '''' ELSE ''<em>desde '' + CONVERT(VARCHAR(5), @F_V1, 103) + ''</em>'' END + ''</div></div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-sec">Por consultor</div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-tb"><div class="vct-pv-agw-tr is-h"><span>Consultor</span><span>Visita</span><span>Detallado</span><span>Sin detallar</span><span>Uso</span></div>''' + NCHAR(10) + N'                 + ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-tr"><span><b>'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN EXISTS (SELECT 1 FROM #EQ Q WHERE Q.TIPO = ''CONSULTOR'' AND Q.ID_ENT = VC.ID_CONSULTOR AND Q.ROL_COD = ''CONSULTOR_LIDER'') THEN ''<i class="vct-pv-agw-lid">L&iacute;der</i>'' ELSE '''' END + ''</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)))), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(DD.H, 0))), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) > ISNULL(DD.H, 0) THEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) - ISNULL(DD.H, 0) ELSE 0 END)), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-bar"><span class="is-plan" style="width:'' + CONVERT(VARCHAR(10), CASE WHEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) <= 0 THEN 0' + NCHAR(10) + N'                                             WHEN ISNULL(DD.H, 0) >= ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) THEN 100' + NCHAR(10) + N'                                             ELSE CONVERT(INT, ROUND(ISNULL(DD.H, 0) * 100.0 / ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)), 0)) END) + ''%"></span></span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK)' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = VC.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 OUTER APPLY (SELECT SUM(D.HORAS) AS H FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID AND D.ID_CONSULTOR = VC.ID_CONSULTOR AND D.TIPO = ''REALIZADO'') DD' + NCHAR(10) + N'                                 WHERE VC.ID_VISITA = A.ID ORDER BY Y.NOM' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''') + ''</div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-cols">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">&#10003; Trabajado en esta visita<span class="vct-360-badge is-active">'' + CONVERT(VARCHAR(10), ISNULL(R.NR, 0)) + '' desarrollo'' + CASE WHEN ISNULL(R.NR, 0) = 1 THEN '''' ELSE ''s'' END + '' &middot; '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</span></div>''' + NCHAR(10) + N'                 + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'')' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN '' &middot; Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') ELSE '''' END + ''</span></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + '' h'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''), ''<div class="vct-plt-empty">Sin desarrollos realizados en esta visita.</div>'')' + NCHAR(10) + N'                 + ''</div>''' + NCHAR(10) + N'                 + CASE WHEN A.DESDE > @HOY' + NCHAR(10) + N'                        THEN ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">Planificado para esta visita<span class="vct-360-badge is-planned">'' + CONVERT(VARCHAR(10), ISNULL(R.NP, 0)) + ''</span></div>''' + NCHAR(10) + N'                           + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'')' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN '' &middot; Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') ELSE '''' END + ''</span></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + ''&ndash;'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''PLANIFICADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''), ''<div class="vct-plt-empty">Nada planificado para esta visita.</div>'')' + NCHAR(10) + N'                           + ''</div>''' + NCHAR(10) + N'                        ELSE ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">&rarr; Para trabajar en la pr&oacute;xima visita'' + CASE WHEN NX.FD IS NOT NULL THEN '' ('' + CONVERT(VARCHAR(5), NX.FD, 103) + '')'' ELSE '''' END' + NCHAR(10) + N'                           + ''<span class="vct-360-badge is-planned">'' + CONVERT(VARCHAR(10), ISNULL(NXP.N, 0) + ISNULL(PP.N, 0)) + ''</span></div>''' + NCHAR(10) + N'                           + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'')' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN '' &middot; Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') ELSE '''' END + ''</span></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + ''&ndash;'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE NX.ID IS NOT NULL AND D.ID_VISITA = NX.ID AND D.TIPO = ''PLANIFICADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''')' + NCHAR(10) + N'                                    + ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it is-paso"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; pr&oacute;ximo paso de esta visita</span></div><span class="vct-pv-agw-hs">&ndash;</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' AND ISNULL(D.PROXIMO_PASO, '''') <> '''' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''),' + NCHAR(10) + N'                                    ''<div class="vct-plt-empty">'' + CASE WHEN NX.ID IS NULL THEN ''No hay una pr&oacute;xima visita cargada en la agenda.'' ELSE ''Nada planificado para la pr&oacute;xima visita.'' END + ''</div>'')' + NCHAR(10) + N'                           + ''</div>'' END' + NCHAR(10) + N'                 + ''</div></div>''' + NCHAR(10) + N'            FROM #AGV A' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END) AS H,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS NR,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END) AS NP' + NCHAR(10) + N'                         FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID) R' + NCHAR(10) + N'            OUTER APPLY (SELECT COUNT(*) AS N FROM dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK) WHERE VC.ID_VISITA = A.ID) NC' + NCHAR(10) + N'            OUTER APPLY (SELECT TOP 1 V2.ID, V2.FECHA_DESDE AS FD FROM dbo.VCT_PROYECTOS_VISITAS V2 WITH(NOLOCK)' + NCHAR(10) + N'                         WHERE V2.ID_PROYECTO = @ID_PROYECTO AND CONVERT(DATE, V2.FECHA_DESDE) > CONVERT(DATE, A.DESDE)' + NCHAR(10) + N'                           AND UPPER(LTRIM(RTRIM(ISNULL(V2.ESTADO,'''')))) NOT IN (''CANCELADO'',''ANULADO'')' + NCHAR(10) + N'                         ORDER BY V2.FECHA_DESDE, V2.ID) NX' + NCHAR(10) + N'            OUTER APPLY (SELECT COUNT(*) AS N FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE NX.ID IS NOT NULL AND D.ID_VISITA = NX.ID AND D.TIPO = ''PLANIFICADO'') NXP' + NCHAR(10) + N'            OUTER APPLY (SELECT COUNT(*) AS N FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' AND ISNULL(D.PROXIMO_PASO, '''') <> '''') PP' + NCHAR(10) + N'            ORDER BY A.DESDE, A.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');';
    SET @N = (DATALENGTH(@D) - DATALENGTH(REPLACE(@D, @NE, N''))) / DATALENGTH(@NE);
    IF @N = 1 SET @D = REPLACE(@D, @NE, @RE); ELSE SET @F = @F + N' agw(' + CONVERT(NVARCHAR(10), @N) + N')';
    IF @F <> N''
        PRINT 'FALLO: no se encontraron en la definicion vigente los puntos:' + @F + '. No se cambio nada.';
    ELSE
    BEGIN
        SET @s = CHARINDEX(N'PROCEDURE', @D);
        SET @p = CASE WHEN @s > 40 THEN @s - 40 ELSE 1 END;
        IF CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) > 0 AND CHARINDEX(N'OR ALTER', SUBSTRING(@D, @p, 40)) = 0
            SET @D = STUFF(@D, @p + CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) - 1, 6, N'ALTER ');
        BEGIN TRY
            EXEC sys.sp_executesql @D;
            PRINT 'OK   VCT_MAIN_PROYECTO_V360 actualizado (PL_DES_V5). Subir vct-proyecto-v360.css (v47) y vct-proyecto-v360.js (v39).';
        END TRY
        BEGIN CATCH
            PRINT 'FALLO al actualizar VCT_MAIN_PROYECTO_V360 (no se cambio): ' + ERROR_MESSAGE() + ' (linea ' + CONVERT(VARCHAR(10), ERROR_LINE()) + ')';
        END CATCH;
    END;
END;
GO
